-- Isolated H2 integration fixtures only; never a production migration.
CREATE TABLE IF NOT EXISTS sys_user(id BIGINT AUTO_INCREMENT PRIMARY KEY,display_name VARCHAR(50),enabled BOOLEAN,password VARCHAR(255),role VARCHAR(20),username VARCHAR(50) UNIQUE);
CREATE TABLE IF NOT EXISTS station(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255),address VARCHAR(255),description VARCHAR(255),status VARCHAR(30),latitude DECIMAL(10,7),longitude DECIMAL(10,7),coordinate_type VARCHAR(16));
CREATE TABLE IF NOT EXISTS charger(id BIGINT AUTO_INCREMENT PRIMARY KEY,station_id BIGINT,code VARCHAR(255) UNIQUE,name VARCHAR(255),status VARCHAR(30),row_name VARCHAR(30),enabled BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS connector(id BIGINT AUTO_INCREMENT PRIMARY KEY,charger_id BIGINT,code VARCHAR(255) UNIQUE,name VARCHAR(255),rated_power INT,status VARCHAR(30));
CREATE TABLE IF NOT EXISTS price_period(id BIGINT AUTO_INCREMENT PRIMARY KEY,station_id BIGINT,start_time TIME,end_time TIME,electricity_price DECIMAL(10,4),service_price DECIMAL(10,4));
CREATE TABLE IF NOT EXISTS charge_order(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_no VARCHAR(255) UNIQUE,station_id BIGINT,connector_id BIGINT,plate_number VARCHAR(255),status VARCHAR(30),test_order BOOLEAN,archived BOOLEAN,archived_at TIMESTAMP,start_time TIMESTAMP,end_time TIMESTAMP,energy_kwh DECIMAL(12,3),electricity_fee DECIMAL(12,2),service_fee DECIMAL(12,2),total_amount DECIMAL(12,2),owner_username VARCHAR(50),payment_status VARCHAR(20),payment_method VARCHAR(20),payment_no VARCHAR(50) UNIQUE,paid_at TIMESTAMP,metering_source VARCHAR(24),simulated_power_watts INT,price_snapshot TEXT,station_name_snapshot VARCHAR(255),socket_code_snapshot VARCHAR(255),failure_reason VARCHAR(500));
CREATE TABLE IF NOT EXISTS audit_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(64),role VARCHAR(32),method VARCHAR(10),path VARCHAR(255),status_code INT,client_ip VARCHAR(64),created_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS repair_ticket(id BIGINT AUTO_INCREMENT PRIMARY KEY,owner_username VARCHAR(50) NOT NULL,station_id BIGINT NOT NULL,charger_id BIGINT NOT NULL,connector_id BIGINT,station_name VARCHAR(255),device_code VARCHAR(255),socket_code VARCHAR(255),description VARCHAR(300),status VARCHAR(20),resolution VARCHAR(500),handler_username VARCHAR(50),request_key VARCHAR(64),created_at TIMESTAMP,updated_at TIMESTAMP,UNIQUE(owner_username,request_key));
